/** Every command's name, in GlesDispatch's order: g_gl's members are this many pointers. */
constexpr size_t kCommandCount = 574;
extern const char* const kCommandNames[kCommandCount];

/** A hooked command: its name, our replacement, and the dispatch slot its real entry point goes in. */
struct HookEntry {
    const char* name;
    void* hook;
    void** real;
};
constexpr size_t kHookCount = 447;
extern const HookEntry kHooks[kHookCount];

